// libvsql.c is libvsql, the SQL/CLI (ISO/IEC 9075-3) shared library (see libvsql.h), as C generated by V for each OS and
// architecture, merged into one file by scripts/amalgamation-merge.py. It
// needs no other C files, see Makefile for how to build it.
//
// V can generate one C file for every OS and architecture (-os cross), but
// that C has no garbage collector (https://github.com/vlang/v/issues/31421), so
// the C is generated on each OS and architecture instead, and the parts that
// are different are inside "#if defined(VSQL_LINUX)" and so on.
//
// It has the Boehm garbage collector (gc.c, see its license below) and helpers
// from V (see LICENSE-V).
#if defined(_WIN32)
#define VSQL_WINDOWS
#elif defined(__APPLE__)
#define VSQL_MACOS
#elif defined(__linux__)
#define VSQL_LINUX
#endif

#if defined(__x86_64__) || defined(_M_X64)
#define VSQL_AMD64
#elif defined(__aarch64__) || defined(_M_ARM64)
#define VSQL_ARM64
#endif

#if !((defined(VSQL_LINUX) && defined(VSQL_AMD64)) || (defined(VSQL_LINUX) && defined(VSQL_ARM64)) || (defined(VSQL_MACOS) && defined(VSQL_AMD64)) || (defined(VSQL_MACOS) && defined(VSQL_ARM64)) || (defined(VSQL_WINDOWS) && defined(VSQL_AMD64)) || (defined(VSQL_WINDOWS) && defined(VSQL_ARM64)))
#error "There is no generated C for this OS and architecture."
#endif

#if defined(VSQL_LINUX) /* vsql platform */
#define _GNU_SOURCE 1
#endif /* vsql platform */
#if defined(VSQL_LINUX) || defined(VSQL_MACOS) /* vsql platform */
#define USE_MMAP 1
#define USE_MUNMAP 1
#define HANDLE_FORK 1
#endif /* vsql platform */
#define GC_THREADS 1
#define THREAD_LOCAL_ALLOC 1
#if defined(VSQL_WINDOWS) /* vsql platform */
#define GC_NOT_DLL 1
#define GC_WIN32_THREADS 1
#define NO_MSGBOX_ON_ERROR 1
#define CONSOLE_LOG 1
#endif /* vsql platform */
#define GC_BUILTIN_ATOMIC 1
#define ALL_INTERIOR_POINTERS 1
#if defined(VSQL_MACOS) /* vsql platform */
#define MPROTECT_VDB 1
#define LARGE_CONFIG 1
#endif /* vsql platform */
#define V_GCBOEHM_NATIVE 1
#if defined(VSQL_WINDOWS) /* vsql platform */
#define _IONBF 4
#define _IOLBF 64
#endif /* vsql platform */
#define V_THREAD_STACK_SIZE 8388608
#if defined(VSQL_MACOS) /* vsql platform */
#define sem_t vsql_gc_sem_t
#define sem_init vsql_gc_sem_init
#define sem_post vsql_gc_sem_post
#define sem_wait vsql_gc_sem_wait
#define sem_destroy vsql_gc_sem_destroy
#endif /* vsql platform */
